// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set owner to address(1)
        vm.prank(address(0));
        c.transferOwnership(address(1));
        // First call to owned() by address(1) — works in both
        vm.prank(address(1));
        c.owned();
        // Second call to owned() by address(1) — reference: owner unchanged, bug: owner becomes msg.sender (still 1)
        vm.prank(address(1));
        c.owned();
        // Now transfer ownership to address(2) by current owner (reference says 1, bug says 1 still)
        vm.prank(address(1));
        c.transferOwnership(address(2));
        // Third call to owned() by address(2) — reference: passes because owner=2, bug: owner still 1 so fails
        vm.prank(address(2));
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

