pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set owner to address(1)
        vm.prank(address(0)); // default owner is address(0)
        c.transferOwnership(address(1));

        // Step 2: First call to owned() as address(1) — works
        vm.prank(address(1));
        c.owned();

        // Step 3: Second call to owned() as address(2) — on reference will revert, on buggy will succeed and change owner
        vm.prank(address(2));
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert: on reference, owned() reverted because msg.sender != owner, so owner remains address(1)
        // On buggy, owned() succeeded and set owner to address(2)
        assertEq(c.owner(), address(1));
    }
}

