pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set owner to address(this) by first transferring ownership (but only owner can, so set via prank from default owner address(0)?)
        // Actually, initial owner is address(0). Since onlyOwner requires msg.sender == owner, and owner is address(0), nobody can transfer ownership legitimately.
        // To get a non-owner to call owned() and observe a revert difference, we need an owner that is not address(0).
        // But we cannot transfer ownership because onlyOwner blocks. So we use the trick: deploy with a different owner by modifying setup? Not allowed.
        // Instead, note that the buggy version's modifier is removed, so anyone can call transferOwnership and then owned() will be callable by anyone (still).
        // But the reference will have owner unchanged (address(0)), so a call to owned() from any non-zero address will revert.
        // Concrete scenario: (1) A random user calls c.transferOwnership(address(0x123)) — on reference, reverts because owner is address(0) and msg.sender != owner; on buggy, succeeds, setting owner to 0x123.
        // (2) Then the same user calls c.owned() — on reference, the prior revert never happened, but now the reference still has owner = address(0) so a call from this user reverts; on buggy, the owned() call succeeds.
        // But we need a single assert that the reference succeeds and bug fails. Actually after step 1, buggy has owner = 0x123; reference owner remains address(0).
        // Then calling owned() from the same user (0x123) — reference: owner is address(0) so revert; buggy: owner is 0x123 so passes. That yields divergence: reference reverts, buggy passes.
        // Let's implement this.
        vm.prank(address(0x123));
        c.transferOwnership(address(0x123)); // reference reverts here, but we need to catch it
        // Actually we need to handle revert in reference vs success in buggy. So wrap the bound call in try/catch.
        bool ok;
        vm.prank(address(0x123));
        try c.transferOwnership(address(0x123)) {
            ok = true;
        } catch {
            ok = false;
        }
        // After this, ok = false for reference, true for buggy.
        assertTrue(ok == false, "reference must revert");
    }
}

